from datetime import datetime
from typing import Optional, List, Dict, Any, Literal
from pydantic import BaseModel, Field, ConfigDict
from app.schemas.decision import DecisionRecordResponse
from app.schemas.approval import ApprovalResponse
from app.schemas.task import TaskResponse


class UserRequestClassification(BaseModel):
    """Structured classification generated by PA when the user sends a message."""
    intent_type: Literal["PROJECT", "SIMPLE_TASK", "QUESTION", "DECISION_REQUEST", "TECH_COMMAND"] = Field(
        ..., description="Categorization of user request"
    )
    summary: str = Field(..., description="High-level understanding of user request")
    target_agent: str = Field(default="pa", description="Recommended primary agent: pa, archy, elder, techy")
    requires_planning: bool = Field(default=False, description="Whether Archy should be engaged to create a project plan")
    requires_elder_review: bool = Field(default=False, description="Whether Elder architectural review is required")
    immediate_reply: Optional[str] = Field(default=None, description="Direct answer if it is a question or simple task")
    confidence: float = Field(default=1.0, ge=0.0, le=1.0)


class TechnologyChoice(BaseModel):
    component: str = Field(..., description="e.g. Backend, Database, Ingress")
    choice: str = Field(..., description="e.g. FastAPI, PostgreSQL, Docker Compose")
    reason: str = Field(..., description="Why this technology is chosen for the VICKY server")
    alternatives: List[str] = Field(default_factory=list, description="Other options considered")


class TaskPlanItem(BaseModel):
    title: str = Field(..., description="Task title")
    description: str = Field(default="", description="Task specification & context")
    priority: str = Field(default="MEDIUM", description="LOW, MEDIUM, HIGH, CRITICAL")
    assignee: str = Field(default="techy", description="Agent responsible for execution")
    expected_result: str = Field(default="", description="Verifiable outcome required for completion")
    estimated_complexity: str = Field(default="MEDIUM", description="LOW, MEDIUM, HIGH")


class MilestonePlan(BaseModel):
    title: str = Field(..., description="Milestone title")
    description: str = Field(default="", description="Scope of milestone")
    tasks: List[TaskPlanItem] = Field(default_factory=list, description="Child tasks under this milestone")


class ArchyProjectPlan(BaseModel):
    """Comprehensive structured project blueprint formulated by Archy."""
    project_name: str = Field(..., description="Clean, descriptive title for the project")
    objective: str = Field(..., description="Primary goal of the project")
    problem_statement: str = Field(default="", description="Problem or gap this project addresses")
    functional_requirements: List[str] = Field(default_factory=list, description="Functional capabilities")
    non_functional_requirements: List[str] = Field(default_factory=list, description="Reliability, security, performance")
    proposed_architecture: str = Field(..., description="Architectural design summary")
    technology_choices: List[TechnologyChoice] = Field(default_factory=list, description="Components and tools selected")
    components: List[Dict[str, Any]] = Field(default_factory=list, description="Component breakdown")
    dependencies: List[str] = Field(default_factory=list, description="Internal and external dependencies")
    milestones: List[MilestonePlan] = Field(default_factory=list, description="Milestones and hierarchical tasks")
    risks: List[str] = Field(default_factory=list, description="Identified technical/operational risks")
    assumptions: List[str] = Field(default_factory=list, description="Assumptions made in this blueprint")
    estimated_complexity: str = Field(default="MEDIUM", description="LOW, MEDIUM, HIGH")
    clarification_questions: List[str] = Field(default_factory=list, description="Questions for the human if any")


class ElderReview(BaseModel):
    """Structured architectural evaluation formulated by Elder."""
    decision: Literal["APPROVE", "REVISE", "REJECT"] = Field(
        ..., description="Elder recommendation on whether plan should proceed, be revised, or rejected"
    )
    confidence: float = Field(default=0.9, ge=0.0, le=1.0)
    review_summary: str = Field(..., description="High-level senior advisor assessment")
    technical_risks: List[str] = Field(default_factory=list, description="Technical risks identified")
    operational_risks: List[str] = Field(default_factory=list, description="Failure modes and server stability risks")
    concerns: List[str] = Field(default_factory=list, description="Unnecessary complexity or maintainability issues")
    recommendations: List[str] = Field(default_factory=list, description="Actionable recommendations")
    alternatives: List[str] = Field(default_factory=list, description="Simpler or better alternative architectures")
    required_changes: List[str] = Field(default_factory=list, description="Changes Archy must make before approval")


class ArchyPlanRevision(BaseModel):
    """Revised plan after incorporating Elder's feedback."""
    revision_summary: str = Field(..., description="Summary of modifications made in response to Elder")
    changes_applied: List[str] = Field(default_factory=list, description="Explicit changes applied")
    revised_architecture: str = Field(..., description="Updated architectural design")
    revised_milestones: List[MilestonePlan] = Field(default_factory=list, description="Updated tasks and milestones")


class PARequestInput(BaseModel):
    """Input message from user to PA."""
    message: str = Field(..., description="User message, request, idea, or command")
    project_id: Optional[str] = Field(default=None, description="Optional associated project context")


class PAResponse(BaseModel):
    """PA's communicative response to the user."""
    message: str = Field(..., description="User-facing conversational response")
    intent: str = Field(..., description="Classified intent")
    action_taken: str = Field(..., description="Summary of organizational action triggered")
    project_id: Optional[str] = None
    task_id: Optional[str] = None
    approval_id: Optional[str] = None
    requires_human_approval: bool = False
    proposal_summary: Optional[str] = None
    severity: Literal["INFO", "WARNING", "CRITICAL"] = "INFO"


class HumanApprovalSubmission(BaseModel):
    """Human decision submitted for a project approval request."""
    decision: Literal["APPROVE", "REJECT", "REQUEST_CHANGES"] = Field(
        ..., description="Decision from human operator"
    )
    notes: Optional[str] = Field(default=None, description="Feedback or instructions for the team")
    approved_by: str = Field(default="user", description="Identifier of human operator")


class ProjectTimelineItem(BaseModel):
    """Unified timeline entry for a project."""
    timestamp: datetime
    type: str  # "EVENT", "MESSAGE", "DECISION", "TASK_UPDATE", "APPROVAL"
    source: str
    title: str
    details: Dict[str, Any] = Field(default_factory=dict)


class OrganizationStatus(BaseModel):
    """Global organization overview presented by PA."""
    active_projects_count: int
    pending_approvals_count: int
    running_tasks_count: int
    agents_status: Dict[str, str]
    recent_critical_events: List[Dict[str, Any]] = Field(default_factory=list)
